 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 160" role="img" aria-label="Pixel landscape for Signal Lost, with a small explorer and signal beacons" shape-rendering="crispEdges"><rect width="240" height="160" fill="#c6d5a5"/><rect width="240" height="90" fill="#b2c598"/><path d="M0 80h16V64h16V48h16v16h16v16h16V64h16V48h16V32h16v16h16v16h16V48h16V32h16v16h16v16h16v16h16v16H0z" fill="#8baf87"/><path d="M0 95h240v12H0zm0 40h240v25H0z" fill="#b4c492"/><path d="M0 112h72v-8h40v-8h40v8h88v15h-88v-8h-40v8H72v8H0z" fill="#dce0b0"/><path d="M0 113h72v-8h40v-8h40" fill="none" stroke="#a8be8c" stroke-width="2"/><g fill="#6e9b72"><path d="M16 94v-8h5v-8h5v8h5v8zM183 94v-8h5v-8h5v8h5v8zM207 78v-8h5v-8h5v8h5v8z"/><path d="M30 143v-6h3v6h3v-4h3v7H27v-5zM165 140v-6h3v6h3v-4h3v7h-12v-5zM70 94v-6h3v6h3v-4h3v7H67v-5z"/></g><g fill="#81996b"><rect x="21" y="94" width="5" height="7"/><rect x="188" y="94" width="5" height="7"/><rect x="212" y="78" width="5" height="7"/></g><g fill="#f1da87"><path d="m152 77 4-6 4 6-4 6zM45 128l4-6 4 6-4 6zM202 119l4-6 4 6-4 6z"/></g><ellipse cx="118" cy="122" rx="9" ry="3" fill="#9caf85"/><path d="M113 103h11v4h3v9h-3v8h-5v-4h-3v4h-4v-9h-2v-8h3z" fill="#3f6656"/><path d="M113 101h11v8h-11z" fill="#eee0ac"/><path d="M111 100h14v5h-14zM115 98h9v3h-9z" fill="#677b5b"/><rect x="116" y="108" width="7" height="9" fill="#c8a67d"/><rect x="121" y="105" width="2" height="2" fill="#3d5949"/><rect x="16" y="9" width="46" height="13" fill="#4f7259"/><text x="20" y="18" fill="#e2e6bb" font-family="monospace" font-size="7">SIGNAL 0/3</text></svg>`;
