function renderShell(){
 const nav=[['home','Your journey','home'],['map','Mission map','map'],['lab','Pixel lab','lab'],['review','Recall deck','cards'],['notes','Field notes','notes'],['resources','Resources','book']];
 $('#app').innerHTML=`<div class="shell"><div class="menu-backdrop"></div><aside class="sidebar" aria-label="Main navigation"><a class="brand" href="#home"><img src="./favicon.svg" alt=""><span class="brand-text">cartridge<small>ACADEMY</small></span></a><p class="sidebar-label">YOUR WORKSPACE</p><nav>${nav.map(([id,label,ic])=>`${id==='notes'?'<div class="sidebar-rule"></div>':''}<a class="nav-link" data-nav="${id}" href="#${id}">${icon(ic,17)}<span>${label}</span>${id==='review'?`<span class="nav-badge" id="review-count">${dueCards().length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="project-box"><div class="project-label">YOUR BUILD</div><strong><i class="dot"></i> Signal Lost</strong><span class="mono" id="project-path">${esc(state.path)}</span></div><button class="profile" id="settings-button"><span class="avatar">P1</span><span class="profile-name">Player one<small>Returning developer</small></span>${icon('settings',16)}</button></div></aside><div class="workspace"><header class="topbar"><button class="mobile-menu" aria-label="Open navigation">${icon('menu',20)}</button><div class="breadcrumb">WORKSPACE <span id="breadcrumb-current">YOUR JOURNEY</span></div><div class="top-actions"><button class="top-icon" id="search-button" aria-label="Search missions">${icon('search',16)}<span>Find a mission</span><kbd>/</kbd></button><button class="focus-button" id="focus-button">${icon('clock',13)}<span id="focus-label">${state.minutes} min focus</span></button></div></header><main id="main" tabindex="-1"></main></div></div>`;
 $('#settings-button').onclick=openSettings;$('#search-button').onclick=openSearch;$('#focus-button').onclick=openFocus;
 $('.mobile-menu').onclick=()=>{$('.sidebar').classList.toggle('open');$('.menu-backdrop').classList.toggle('open');};
 $('.menu-backdrop').onclick=closeMenu;
}
function closeMenu(){$('.sidebar').classList.remove('open');$('.menu-backdrop').classList.remove('open');}
function go(hash){if(location.hash===hash)renderRoute();else location.hash=hash;}
function renderRoute(){
 if(routeCleanup){routeCleanup();routeCleanup=null;}
 closeMenu();const hash=location.hash.slice(1)||'home';const [page,arg]=hash.split('/');
 const navPage=page==='mission'?'map':page;
 $$('.nav-link').forEach(a=>{a.classList.toggle('active',a.dataset.nav===navPage);if(a.dataset.nav===navPage)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 const labels={home:'YOUR JOURNEY',map:'MISSION MAP',lab:'PIXEL LAB',review:'RECALL DECK',notes:'FIELD NOTES',resources:'RESOURCES',mission:'MISSION '+String(arg).padStart(2,'0')};
 $('#breadcrumb-current').textContent=labels[page]||labels.home;
 $('#review-count').textContent=dueCards().length;
 const views={home:renderHome,map:renderMap,lab:renderLabPage,review:()=>{reviewStarted=false;renderReview();},notes:renderNotes,resources:renderResources,mission:()=>renderMission(Number(arg))};
 (views[page]||renderHome)();
 document.title=`${page==='mission'?(missions.find(m=>m.id===Number(arg))?.title||'Mission'):({home:'Your journey',map:'Mission map',lab:'Pixel lab',review:'Recall deck',notes:'Field notes',resources:'Resources'}[page]||'Your journey')} · Cartridge Academy`;
 window.scrollTo(0,0);
}
function heading(title,subtitle,extra=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${extra}</div>`;}
function footer(){return `<div class="footer-note"><span>Made for small steps and big ideas. ${icon('leaf',10)}</span><button class="text-link" data-export>Saved in this browser ${icon('download',11)}</button></div>`;}
function bindFooter(){const b=$('[data-export]');if(b)b.onclick=exportProgress;}
function renderHome(){
 const n=nextMission(), w=worlds.find(w=>w.id===n.world)||worlds[0], done=state.completed.length, pct=progress(), finished=done===missions.length;
 $('#main').innerHTML=`${heading(finished?'Your next game starts with you.':done?'Welcome back, builder.':'Your next adventure starts here.',finished?'You’ve built, tested, and explained a whole game. Choose what to make next.':done?'Your game is a little closer. Pick up where you left off.':'A little C++. A few pixels. A game that’s entirely yours.',`<div class="player-label">PLAYER 01<br><b>● READY WHEN YOU ARE</b></div>`)}
 <section class="hero"><div class="hero-copy"><div class="eyebrow">${icon('flag',12)} WORLD ${String(w.id).padStart(2,'0')} · ${esc(w.title)}</div><h2>${finished?'Your world.<br>Your game.':done?'One more step.<br>A little more game.':'Big ideas.<br>Tiny screen.'}</h2><p>${finished?'Revisit your capstone, improve a tricky mechanic, or sketch a fresh cartridge. You have a process to build on.':done?`Next up: ${esc(n.title)}. Make one change you can see, test, and explain.`:'Build your first Game Boy Advance game, one hands-on mission at a time.'}</p><div class="hero-actions"><a class="button" href="#mission/${n.id}">${finished?'Revisit your capstone':`${done?'Continue':'Start'} mission ${String(n.id).padStart(2,'0')}`} ${icon('arrow',15)}</a><a href="#map" class="text-link">Explore the path ${icon('chevron',12)}</a></div></div><div class="hero-visual"><span class="floating-code one">// a new adventure awaits</span>${consoleSVG()}<span class="floating-code two"><span style="color:#8da675">bn::</span>core::update();</span><span class="star">✧</span></div></section>
 <div class="session-strip"><a class="session-card" href="#mission/4"><span class="icon-tile">${icon('code',18)}</span><span><strong>A C++ reboot</strong><small>Rusty is a starting point.</small></span>${icon('chevron',13)}</a><a class="session-card" href="#lab"><span class="icon-tile purple">${icon('art',18)}</span><span><strong>Learn by making</strong><small>Draw it. Code it. Understand it.</small></span>${icon('chevron',13)}</a><button class="session-card" id="small-session" style="text-align:left"><span class="icon-tile green">${icon('clock',18)}</span><span><strong>${state.minutes} minutes is enough</strong><small>Small sessions. Real progress.</small></span>${icon('chevron',13)}</button></div>
 <div class="panel starting-point" style="margin-bottom:25px;padding:14px 18px;display:flex;gap:13px;align-items:center"><span class="icon-tile green">${icon('terminal',17)}</span><div style="flex:1"><strong style="font-size:11px">Your starting point: a player that already moves.</strong><p style="font-size:10px;color:#8b9680;margin:2px 0 0">Your existing 16×16 sprite and D-pad code are the foundation. Investigate the screen-edge behavior next.</p></div><a href="#mission/5" class="text-link" style="white-space:nowrap">Try the experiment ${icon('arrow',12)}</a></div><div class="dashboard-columns"><div><div class="section-head"><h2>Your adventure map</h2><a class="text-link" href="#map">${done} / ${missions.length} missions ${icon('arrow',12)}</a></div><section class="panel journey-list">${worlds.map(world=>{const ms=missions.filter(m=>m.world===world.id),count=ms.filter(m=>complete(m.id)).length;return `<a href="#map/world-${world.id}" class="world-row ${w.id===world.id?'current':''}"><span class="world-number">${count===ms.length?icon('check',15):String(world.id).padStart(2,'0')}</span><span><h3>${esc(world.title)}</h3><p>${esc(world.skills)}</p></span><span class="world-status">${count===ms.length?'Complete':w.id===world.id?'YOU ARE HERE':`${count} / ${ms.length}`}</span>${icon('chevron',12)}</a>`;}).join('')}</section>
 <section class="panel momentum"><div><h3>Momentum, without the pressure.</h3><p>Show up, make a small thing, come back when you can.</p></div><div class="activity">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return `<span class="day" title="${key}: ${state.activities[key]||0} learning actions"><i class="${state.activities[key]?'active':''}"></i>${d.toLocaleDateString('en',{weekday:'narrow'})}</span>`;}).join('')}</div></section></div>
 <aside class="dashboard-rail"><section class="panel cartridge-card"><div class="eyebrow">YOUR FUTURE CARTRIDGE</div><h3>Signal Lost</h3><p>A small explorer. Three lost signals.<br>An entire world you’ll make your own.</p><div class="mini-game">${sceneSVG()}</div><div class="cartridge-stats"><span>${pct}% built</span><span>${done*100} XP</span></div><div class="progress-line" role="progressbar" aria-label="Course progress" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><span style="width:${pct}%"></span></div></section><section class="panel small-panel"><div class="recall-head"><h3>A little recall goes a long way.</h3><span class="tag purple">${dueCards().length} due</span></div><p>Bring yesterday’s ideas into today’s code. A few questions, from memory.</p><a class="button secondary" href="#review">Open recall deck ${icon('arrow',13)}</a></section><section class="panel small-panel"><div class="recall-head"><h3>Your toolkit</h3>${icon('terminal',15)}</div><div class="tool-chips">${['C++','Butano','mGBA','GNU GDB','Neovim','Git + GitHub',state.artTool,'WSL Ubuntu'].map(t=>`<span>${esc(t)}</span>`).join('')}</div></section></aside></div>${footer()}`;
 $('#small-session').onclick=openFocus;bindFooter();
}
function renderMap(){
 $('#main').innerHTML=`${heading('A game is built one mission at a time.','7 worlds · 28 missions · one original game')}<p class="page-intro">Start with a working build, refresh your C++, draw your own art, and finish with an independent release. Each mission is one focused sitting; bigger tasks can take several. Explore freely and return to the path when you’re ready.</p><div class="map-grid">${worlds.map(w=>{const ms=missions.filter(m=>m.world===w.id),c=ms.filter(m=>complete(m.id)).length;return `<section class="panel world-card" id="world-${w.id}"><div class="world-card-top"><span class="icon-tile ${w.color}">${icon(w.icon,21)}</span><div><span class="eyebrow muted">WORLD ${String(w.id).padStart(2,'0')} · ${c}/${ms.length}</span><h2>${esc(w.title)}</h2></div></div><p>${esc(w.desc)}</p><div class="progress-line" style="margin-bottom:18px"><span style="width:${c/ms.length*100}%"></span></div>${ms.map(m=>`<a class="mission-link ${complete(m.id)?'done':''}" href="#mission/${m.id}"><span class="num">${complete(m.id)?icon('check',15):String(m.id).padStart(2,'0')}</span><span class="title">${esc(m.title)}</span><span class="duration">${m.minutes} min</span>${icon('chevron',12)}</a>`).join('')}</section>`;}).join('')}</div><div class="milestone">Your final test: design a new mechanic, build it without a recipe, debug it, and explain the decisions behind it. Completion checks are your own recorded observations.</div>${footer()}`;
 bindFooter();const part=location.hash.split('/')[1];if(part)requestAnimationFrame(()=>document.getElementById(part)?.scrollIntoView({behavior:'smooth',block:'start'}));
}
function draftFor(id){return state.drafts[id] ||= {checks:[],quiz:null,prediction:'',reflection:'',transfer:'',evidence:''};}
function renderMission(id){
 const m=missions.find(m=>m.id===id);if(!m){$('#main').innerHTML=`<div class="empty-state">That mission isn’t on the map. <a href="#map">Open the mission map →</a></div>`;return;}
 const w=worlds.find(w=>w.id===m.world),d=draftFor(id);state.lastMission=id;save();
 const firstOfWorld=missions.find(x=>x.world===m.world)?.id===id;
 $('#main').innerHTML=`<a class="back-link" href="#map">← Back to your mission map</a>${heading(`${String(m.id).padStart(2,'0')}. ${esc(m.title)}`,esc(m.subtitle||m.goal))}<div class="lesson-meta" style="margin-top:-10px;margin-bottom:25px"><span class="tag">WORLD ${m.world} · ${esc(w?.title)}</span><span class="tag">${icon('clock',11)} ${m.minutes} min</span>${(m.tags||[]).map(t=>`<span class="tag purple">${esc(t)}</span>`).join('')}${complete(id)?'<span class="tag">✓ COMPLETE</span>':''}</div>
 <div class="lesson-layout"><div><section class="panel lesson-panel"><div class="lesson-section-label eyebrow">${icon('flag',14)} THE MISSION</div><h2>${rich(m.goal)}</h2><p>Work in <code class="inline-code">${esc(state.path)}</code>. This page guides your experiments; your terminal, editor, and emulator are where the real game runs.</p>${firstOfWorld?'<div class="analogy">The loop: predict → build → inspect → explain → try a variation. Aim for an observation you can explain, then leave a note for your next session.</div>':''}</section>
 <section class="panel lesson-panel"><div class="lesson-section-label eyebrow">01 · PREDICT</div><h2>Start with your mental model.</h2><p>${rich(m.recall)}</p><label class="field-label" for="prediction">What do you think will happen, and why?</label><textarea id="prediction" class="text-field" data-draft="prediction" rows="3" placeholder="Take a guess before looking at the example. Uncertainty is welcome.">${esc(d.prediction)}</textarea></section>
 <section class="panel lesson-panel"><div class="lesson-section-label eyebrow">02 · UNDERSTAND</div><h2>What’s happening under the pixels?</h2><p>${rich(m.concept)}</p><div class="analogy">${icon('spark',14)} ${rich(m.analogy)}</div></section>
 <section class="panel lesson-panel"><div class="lesson-section-label eyebrow">03 · BUILD</div><h2>Make one visible change.</h2><ol>${m.steps.map(step=>`<li>${rich(step)}</li>`).join('')}</ol><div class="analogy"><strong>Your experiment</strong><br>${rich(m.challenge)}</div></section>
 <section class="panel lesson-panel"><div class="lesson-section-label eyebrow">04 · INSPECT</div><h2>Does your build hold up?</h2><p>Run each check in your project. Mark it only after you observe the behavior. These are self-reported checks, so capture useful evidence.</p>${m.checks.map((check,i)=>`<label class="check-row"><input type="checkbox" data-check="${i}" ${d.checks.includes(i)?'checked':''}><span>${rich(check)}</span></label>`).join('')}<label class="field-label" for="evidence" style="margin-top:20px">Your evidence</label><textarea class="text-field" data-draft="evidence" id="evidence" rows="3" placeholder="Record a test result, a commit hash, or the bug you reproduced.">${esc(d.evidence)}</textarea></section>
 <section class="panel lesson-panel"><div class="lesson-section-label eyebrow">05 · RETRIEVE</div><h2>Think it through.</h2><p>${rich(m.quiz.question)}</p><div class="quiz-options">${m.quiz.options.map((option,i)=>`<button class="quiz-option ${d.quiz===i?(i===m.quiz.correct?'correct':'incorrect'):''}" data-quiz="${i}" aria-pressed="${d.quiz===i}"><b>${String.fromCharCode(65+i)}</b><span>${rich(option)}</span></button>`).join('')}</div><div id="quiz-feedback">${quizFeedback(m,d)}</div></section>
 <section class="panel lesson-panel"><div class="lesson-section-label eyebrow">06 · EXPLAIN & TRANSFER</div><h2>Make the idea your own.</h2><label class="field-label" for="reflection">Explain the mechanism in your own words.</label><textarea class="text-field" id="reflection" data-draft="reflection" rows="4" placeholder="Why did your change work? What observation would prove your explanation wrong?">${esc(d.reflection)}</textarea><p style="margin-top:20px">${rich(m.transfer)}</p><label class="field-label" for="transfer">What did you try in this new situation?</label><textarea class="text-field" id="transfer" data-draft="transfer" rows="3" placeholder="Try the variation, then note your approach and result.">${esc(d.transfer)}</textarea></section>
 </div><aside class="lesson-aside"><details class="example-wrapper" ${d.prediction.trim().length>=8?'open':''}><summary class="example-summary">Study the worked example <small>Make your prediction first, then compare.</small></summary><div class="code-panel"><div class="code-head"><span>${esc(m.filename||'src/main.cpp')} · ${esc(m.codeLanguage||'cpp')}</span><button id="copy-code" aria-label="Copy code example">${icon('cards',12)} Copy</button></div><pre><code>${esc(m.code)}</code></pre><div class="code-note">${m.codeLanguage==='bash'?'Run and adapt these commands in your WSL terminal.':'A focused example, not a complete game. Adapt it inside your project.'}</div></div></details>
 <section class="panel lesson-panel"><h3>Stuck? Unfold a hint.</h3><p style="font-size:11px">Try an experiment first. Open only as much help as you need.</p>${m.hints.map((h,i)=>`<details class="hint"><summary>Hint ${i+1} · ${['A nudge','A direction','A closer look'][i]||'More help'}</summary><p>${rich(h)}</p></details>`).join('')}</section>
 <section class="panel lesson-panel"><h3>Leave a checkpoint.</h3><p style="font-size:11px">Review the diff before committing. Commit only the files you intend to keep.</p><div class="code-panel" style="margin-bottom:0"><pre style="padding:14px;font-size:9px;white-space:pre-wrap">git diff --staged\ngit commit -m "${esc(m.commit||m.title)}"</pre></div></section>
 <section class="panel lesson-panel"><h3>Go to the source.</h3><div class="source-links">${(m.sources||[]).map(id=>resources.find(r=>r.id===id)).filter(Boolean).map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${icon('external',12)} ${esc(r.title)}</a>`).join('')}</div></section>
 <section class="completion-box"><h3>Build. Understand. Keep going.</h3><p>Your work saves as you type. Come back to this mission whenever you like.</p><div id="completion-requirements"></div><button class="button" id="complete-mission">${complete(id)?'✓ Mission complete':'Complete mission'} ${icon('arrow',14)}</button></section></aside></div>
 <div class="lesson-nav">${id>1?`<a class="button secondary" href="#mission/${id-1}">← Previous mission</a>`:'<span></span>'}${id<missions.length?`<a class="button secondary" href="#mission/${id+1}">Preview next mission ${icon('arrow',14)}</a>`:'<a href="#map" class="button secondary">Return to your map →</a>'}</div>${footer()}`;
 $('[data-draft="prediction"]').oninput=e=>{d.prediction=e.target.value;save();};
 $$('[data-draft]').forEach(el=>el.oninput=()=>{d[el.dataset.draft]=el.value;save();updateCompletion(m,d);});
 $$('[data-check]').forEach(el=>el.onchange=()=>{const i=Number(el.dataset.check);d.checks=el.checked?[...new Set([...d.checks,i])]:d.checks.filter(n=>n!==i);save();updateCompletion(m,d);});
 $$('[data-quiz]').forEach(el=>el.onclick=()=>{d.quiz=Number(el.dataset.quiz);save();$$('[data-quiz]').forEach(b=>{const selected=Number(b.dataset.quiz)===d.quiz;b.className='quiz-option'+(selected?(d.quiz===m.quiz.correct?' correct':' incorrect'):'');b.setAttribute('aria-pressed',String(selected));});$('#quiz-feedback').innerHTML=quizFeedback(m,d);updateCompletion(m,d);});
 $('#copy-code').onclick=()=>copyText(m.code,'Example copied.');
 $('#complete-mission').onclick=()=>{if(complete(id)){go(state.completed.length===missions.length?'#map':`#mission/${nextMission().id}`);return;}if(!requirements(m,d).every(r=>r.done))return;state.completed.push(id);activity();toast(`Mission ${String(id).padStart(2,'0')} complete. Your game is one step closer.`);renderMission(id);$('#review-count').textContent=dueCards().length;};
 updateCompletion(m,d);bindFooter();
}
function quizFeedback(m,d){if(d.quiz===null)return '';return `<div class="feedback ${d.quiz===m.quiz.correct?'':'error'}">${d.quiz===m.quiz.correct?'✓ You’ve got it.':'Try another explanation.'} ${rich(m.quiz.explanation)}</div>`;}
function requirements(m,d){return [{label:'Make a prediction',done:d.prediction.trim().length>=8},{label:'Run every build check',done:m.checks.every((_,i)=>d.checks.includes(i))},{label:'Record an observation',done:d.evidence.trim().length>=10},{label:'Answer the recall question',done:d.quiz===m.quiz.correct},{label:'Explain why it works',done:d.reflection.trim().length>=20},{label:'Try the transfer challenge',done:d.transfer.trim().length>=15}];}
function updateCompletion(m,d){const req=requirements(m,d);$('#completion-requirements').innerHTML=req.map(r=>`<div class="progress-requirements">${r.done?'✓':'○'} ${r.label}</div>`).join('');$('#complete-mission').disabled=!complete(m.id)&&!req.every(r=>r.done);}

function renderLabPage(){
 $('#main').innerHTML=`${heading('Small experiments. Big lightbulb moments.','A playground for the ideas behind your game.')}<p class="page-intro">Move a character, test a collision, slow a frame down, or draw your first sprite. These browser models make the concepts visible. Compile and test your actual C++ game in WSL and mGBA.</p><div id="lab-container"></div>${footer()}`;
 routeCleanup=renderLab($('#lab-container'));bindFooter();
}
function startReview(all=false){reviewQueue=all?[...reviewCards]:dueCards();reviewQueue=reviewQueue.sort(()=>Math.random()-.5);reviewed=0;reviewAttempt='';reviewRevealed=false;reviewStarted=true;renderReview();}
function renderReview(){
 if(!reviewStarted){reviewQueue=dueCards().sort(()=>Math.random()-.5);reviewed=0;reviewStarted=true;}
 const c=reviewQueue[0];
 $('#main').innerHTML=`${heading('A little recall, a stronger foundation.','Try from memory. Compare your reasoning. Come back after a gap.')}<div class="review-layout">${c?`<div class="review-progress"><span>${reviewed} reviewed this session</span><span>${reviewQueue.length} remaining</span></div><section class="review-card"><span class="tag purple">${esc(c.topic)} · MISSION ${String(c.mission).padStart(2,'0')}</span><h2>${rich(c.question)}</h2><label class="field-label" for="review-attempt">Your explanation, before the reveal</label><textarea id="review-attempt" class="text-field" rows="4" placeholder="Write what you remember. A rough attempt is enough.">${esc(reviewAttempt)}</textarea><div id="review-answer-area">${reviewRevealed?reviewAnswer(c):`<button id="reveal-answer" class="button" style="margin-top:18px" ${reviewAttempt.trim().length<3?'disabled':''}>Compare with the explanation ${icon('arrow',14)}</button>`}</div></section><div class="deck-info">Reviews follow completed topics. The first game-loop card is available to get you started. “Got it” schedules a longer gap: 1, 3, 7, 14, then 30 days. “Again” brings it back tomorrow.</div>`:`<section class="panel review-end"><div class="big-icon">${icon('leaf',32)}</div><h2>${reviewed?'Nice work. Let that settle.':'You’re all caught up.'}</h2><p class="muted">${reviewed?`${reviewed} idea${reviewed===1?'':'s'} revisited. Your next reviews are scheduled.`:'More cards open as you complete missions. There’s no penalty for taking a break.'}</p><a class="button" href="#mission/${nextMission().id}">Back to building ${icon('arrow',14)}</a><button class="text-link" id="practice-all" style="display:block;margin:20px auto 0">Explore all ${reviewCards.length} cards</button></section>`}</div>${footer()}`;
 if(c){$('#review-attempt').oninput=e=>{reviewAttempt=e.target.value;if($('#reveal-answer'))$('#reveal-answer').disabled=reviewAttempt.trim().length<3;};if($('#reveal-answer'))$('#reveal-answer').onclick=()=>{reviewRevealed=true;$('#review-answer-area').innerHTML=reviewAnswer(c);bindGrades(c);};if(reviewRevealed)bindGrades(c);}else $('#practice-all').onclick=()=>startReview(true);
 bindFooter();
}
function reviewAnswer(c){return `<div class="review-answer">${rich(c.answer)}</div><a class="text-link" href="${esc(c.url||'#resources')}" target="_blank" rel="noopener noreferrer">Read the source ${icon('external',12)}</a><p class="small muted" style="margin-top:20px;margin-bottom:6px">How well did your explanation match?</p><div class="review-grade"><button class="button secondary" data-grade="again">I need another look</button><button class="button" data-grade="good">Got it ${icon('check',14)}</button></div>`;}
function bindGrades(c){$$('[data-grade]').forEach(b=>b.onclick=()=>{const previous=state.reviews[c.id],level=b.dataset.grade==='good'?Math.min((previous?.level??-1)+1,4):0;const days=b.dataset.grade==='good'?[1,3,7,14,30][level]:1;state.reviews[c.id]={level,due:Date.now()+days*86400000,answer:reviewAttempt,last:Date.now()};activity();reviewQueue.shift();reviewed++;reviewAttempt='';reviewRevealed=false;$('#review-count').textContent=dueCards().length;renderReview();});}

function renderNotes(){
 const missionNotes=Object.entries(state.drafts).filter(([,d])=>d.reflection||d.evidence).map(([id,d])=>({id:Number(id),...d}));
 $('#main').innerHTML=`${heading('Leave a trail for your future self.','A tiny devlog beats trying to remember where you left off.')}<div class="notes-layout"><section class="panel"><div class="section-head"><h2>Your working notebook</h2><span class="tag">AUTOSAVED</span></div><label class="field-label" for="journal">What did you build, discover, or get stuck on?</label><textarea id="journal" class="text-field" placeholder="Today I tried…\nI expected…\nI observed…\nMy next smallest step is…">${esc(state.journal)}</textarea><div class="field-tools"><span class="small muted" id="journal-status">Saved on this browser</span><button class="button secondary" id="download-notes">${icon('download',14)} Export .md</button></div><div class="analogy">Before you stop, write one next action so small you can start it in two minutes. “Reproduce the wall bug” is more useful than “finish collisions.”</div></section><section class="panel"><div class="section-head"><h2>From your missions</h2><span class="tag">${missionNotes.length} entries</span></div>${missionNotes.length?missionNotes.map(d=>{const m=missions.find(m=>m.id===d.id);return `<article class="note-entry"><a href="#mission/${d.id}"><h3>${String(d.id).padStart(2,'0')} · ${esc(m?.title||'Mission')}</h3></a>${d.evidence?`<span class="eyebrow muted" style="font-size:8px">OBSERVATION</span><p>${esc(d.evidence)}</p>`:''}${d.reflection?`<span class="eyebrow muted" style="font-size:8px">EXPLANATION</span><p>${esc(d.reflection)}</p>`:''}</article>`;}).join(''):'<div class="notes-empty">Your explanations and observations will appear here as you work through missions. Start with what surprised you.</div>'}</section></div>${footer()}`;
 $('#journal').oninput=e=>{state.journal=e.target.value;save();$('#journal-status').textContent='Saved just now';};
 $('#download-notes').onclick=()=>download('signal-lost-devlog.md',`# Signal Lost — Devlog\n\n${state.journal}\n\n${missionNotes.map(d=>`## Mission ${d.id}: ${missions.find(m=>m.id===d.id)?.title}\n\nPrediction: ${d.prediction||''}\n\nEvidence: ${d.evidence||''}\n\nReflection: ${d.reflection||''}\n\nTransfer: ${d.transfer||''}`).join('\n\n')}`,'text/markdown');bindFooter();
}
const artResources=[{id:'art-aseprite',title:'Aseprite',url:'https://www.aseprite.org/',type:'Art',note:'My first choice for a dedicated pixel-art workflow: layers, onion skin, frame tags, palette controls, and sprite-sheet exports. Ready-made binaries are paid.'},{id:'art-libresprite',title:'LibreSprite',url:'https://github.com/LibreSprite/LibreSprite',type:'Art',note:'A free, open-source alternative with layers, frames, onion skinning, animation preview, and tiled drawing. A good starting point with no purchase required.'},{id:'art-usenti',title:'Usenti',url:'https://www.coranac.com/projects/#usenti',type:'Art',note:'A small editor for paletted bitmaps. Useful for inspecting and rearranging indexed palettes. Keep it as an optional utility alongside your animation editor.'},{id:'art-indexed',title:'Understand indexed color',url:'https://www.aseprite.org/docs/color-mode/',type:'Art',note:'Learn the difference between an RGB color and a palette index, and why the transparent index matters.'},{id:'art-sheets',title:'Export a sprite sheet',url:'https://www.aseprite.org/docs/sprite-sheet/',type:'Art',note:'Keep an editable master, export an unscaled sheet, and make a separate Butano configuration JSON. Aseprite atlas metadata is a different format.'}];
function renderResources(){
 $('#main').innerHTML=`${heading('A field guide, not a reading backlog.','The right reference, right when you need it.')}<div class="resource-toolbar">${[['docs','Tool references'],['art','Your art tools'],['glossary','Plain-English glossary'],['learning','How learning works']].map(([id,title])=>`<button class="tab-button ${resourceTab===id?'active':''}" data-resource-tab="${id}">${title}</button>`).join('')}</div><div id="resource-content"></div>${footer()}`;
 $$('[data-resource-tab]').forEach(b=>b.onclick=()=>{resourceTab=b.dataset.resourceTab;resourceQuery='';renderResources();});
 const root=$('#resource-content');
 if(resourceTab==='learning')root.innerHTML=`<p class="page-intro">The course applies established learning principles to game development. These sources explain the design; your own evidence and ability to solve new problems are the useful measures of progress.</p><div class="resource-grid">${learningPrinciples.map((p,i)=>`<section class="panel principle"><span class="eyebrow muted">PRINCIPLE ${String(i+1).padStart(2,'0')}</span><h3 style="margin-top:12px">${esc(p.title)}</h3><p>${esc(p.description)}</p><strong>In your missions</strong><p>${esc(p.implementation)}</p><a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer" class="text-link">${esc(p.source)} ${icon('external',12)}</a></section>`).join('')}</div>`;
 else if(resourceTab==='glossary'){root.innerHTML=`<input class="text-field" id="glossary-search" type="search" aria-label="Search the glossary" placeholder="Find a term: RAII, tiles, SRAM…" value="${esc(resourceQuery)}" style="max-width:480px;margin-bottom:22px"><section class="panel" id="glossary-list"></section>`;renderGlossary();$('#glossary-search').oninput=e=>{resourceQuery=e.target.value;renderGlossary();};}
 else{const list=resourceTab==='art'?artResources:resources;root.innerHTML=`${resourceTab==='art'?'<p class="page-intro">Choose one editor and start drawing. Aseprite is the recommended full workflow; LibreSprite is a free alternative. Usenti is useful for palette work. A native Windows editor can sit alongside your WSL toolchain. The Pixel lab is ready for your first experiments.</p>':''}<div class="resource-grid">${list.map(r=>`<a class="panel resource-card" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer"><span class="tag ${resourceTab==='art'?'purple':''}">${esc(r.type||'Documentation')}</span><h3>${esc(r.title)}</h3><p>${esc(r.note||'Official reference for your next experiment.')}</p><div class="resource-bottom"><small>${esc(new URL(r.url).hostname)}</small>${icon('external',14)}</div></a>`).join('')}</div>`;}
 bindFooter();
}
function renderGlossary(){const list=glossary.filter(g=>`${g.term} ${g.definition}`.toLowerCase().includes(resourceQuery.toLowerCase()));$('#glossary-list').innerHTML=list.length?list.map(g=>`<article class="glossary-item"><h3>${esc(g.term)}</h3><p>${esc(g.definition)}</p><code>${esc(g.example)}</code></article>`).join(''):'<p class="empty-state">No matching term. Try “sprite” or “reference”.</p>';}

function openModal(html,label){
 modalLastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(label)}"><div class="modal-heading"><h2>${esc(label)}</h2><button class="icon-button" id="close-modal" aria-label="Close dialog">${icon('close',20)}</button></div>${html}</section></div>`;
 document.body.style.overflow='hidden';$('#close-modal').onclick=closeModal;$('.modal-overlay').onclick=e=>{if(e.target===$('.modal-overlay'))closeModal();};requestAnimationFrame(()=>$('.modal input,.modal textarea,.modal button:not(#close-modal)')?.focus());
}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow='';modalLastFocus?.focus();}
function openSearch(){
 openModal('<input id="mission-search" class="search-input" type="search" placeholder="Sprites, C++, palettes, debugging…" aria-label="Search missions"><div class="search-results" id="search-results"></div><div class="small muted" style="margin-top:14px">Search every mission by title, topic, or goal.</div>','Find your next experiment');
 const render=()=>{const q=$('#mission-search').value.toLowerCase(),found=missions.filter(m=>`${m.title} ${m.tags.join(' ')} ${m.goal} ${m.concept}`.toLowerCase().includes(q));$('#search-results').innerHTML=found.length?found.map(m=>`<a class="search-result" href="#mission/${m.id}"><span><span class="mono muted">${String(m.id).padStart(2,'0')}</span> &nbsp;${esc(m.title)}</span><small>${m.minutes} min ${icon('chevron',11)}</small></a>`).join(''):'<p class="empty-state">No matches. Try “input”, “art”, or “GDB”.</p>';$$('.search-result').forEach(a=>a.onclick=closeModal);};
 $('#mission-search').oninput=render;render();
}
function openSettings(){
 openModal(`<div class="settings-group"><label class="field-label" for="project-setting">Your project folder</label><input id="project-setting" class="text-field" value="${esc(state.path)}"><p>This labels your workspace. The browser cannot inspect your WSL files.</p></div><div class="settings-group"><label class="field-label" for="minutes-setting">A comfortable focus session</label><select class="text-field" id="minutes-setting">${[15,25,45].map(m=>`<option value="${m}" ${state.minutes===m?'selected':''}>${m} minutes</option>`).join('')}</select></div><div class="settings-group"><label class="field-label" for="art-setting">Your art editor</label><select class="text-field" id="art-setting">${['LibreSprite','Aseprite','Usenti','Other editor'].map(s=>`<option ${state.artTool===s?'selected':''}>${s}</option>`).join('')}</select><p>The art missions teach portable skills, so you can change tools later.</p></div><button class="button" id="save-settings" style="width:100%">Save your preferences ${icon('check',14)}</button><div class="sidebar-rule" style="margin:23px 0"></div><div class="settings-group"><h3 style="font-size:14px">Keep a copy of your progress.</h3><p>Mission work, notes, and review scheduling live in this browser. Export a backup to move between devices.</p><div class="settings-actions"><button class="button secondary" id="export-settings">${icon('download',13)} Export progress</button><button class="button secondary" id="import-settings">Import a backup</button><input type="file" id="import-file" accept=".json,application/json" hidden></div></div>`,'Make yourself at home');
 $('#save-settings').onclick=()=>{const newMinutes=Number($('#minutes-setting').value);state.path=$('#project-setting').value.trim()||'~/Unamed-Project';state.minutes=newMinutes;state.artTool=$('#art-setting').value;if(!timerRunning)timerSeconds=newMinutes*60;save();$('#project-path').textContent=state.path;updateTimerUI();closeModal();renderRoute();toast('Your workspace is ready.');};
 $('#export-settings').onclick=exportProgress;$('#import-settings').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const incoming=JSON.parse(await f.text());validateBackup(incoming);if(incoming.pixelProjects)importPixelProjects(incoming.pixelProjects);const {pixelProjects,...restored}=incoming;state={...defaults(),...restored};save();closeModal();timerRunning=false;timerSeconds=state.minutes*60;renderShell();renderRoute();toast('Your progress is restored.');}catch{toast('This backup could not be read. Use a Cartridge Academy export.');}};
}
function validateBackup(s){
 if(!s||s.version!==1||!Array.isArray(s.completed)||!s.completed.every(n=>Number.isInteger(n)&&missions.some(m=>m.id===n))||new Set(s.completed).size!==s.completed.length||typeof s.path!=='string'||typeof s.journal!=='string'||!s.drafts||typeof s.drafts!=='object'||!s.reviews||typeof s.reviews!=='object'||!s.activities||typeof s.activities!=='object'||![15,25,45].includes(s.minutes)||typeof s.artTool!=='string')throw Error('Invalid data');
 for(const [id,d] of Object.entries(s.drafts)){if(!missions.some(m=>String(m.id)===id)||!Array.isArray(d.checks)||!d.checks.every(n=>Number.isInteger(n)&&n>=0&&n<20)||!(d.quiz===null||Number.isInteger(d.quiz))||!['prediction','reflection','transfer','evidence'].every(k=>typeof d[k]==='string'))throw Error('Invalid draft');}
 for(const r of Object.values(s.reviews))if(!r||!Number.isFinite(r.due)||!Number.isInteger(r.level)||r.level<0||r.level>4)throw Error('Invalid review');
 for(const v of Object.values(s.activities))if(!Number.isInteger(v)||v<0)throw Error('Invalid activity');
}
function openFocus(){
 openModal(`<p class="small muted">Pick one visible change. Close the extra tabs. You can stop whenever you need to.</p><div class="timer" id="timer-display"></div><div class="timer-actions"><button class="button" id="timer-toggle"></button><button class="button secondary" id="timer-reset">${icon('refresh',14)} Reset</button></div><p class="focus-tip">A good stopping point: a tested change and a note about what comes next.</p><a href="#mission/${state.lastMission||nextMission().id}" class="text-link" id="timer-mission" style="justify-content:center;display:flex">Open your current mission ${icon('arrow',13)}</a>`,'A little time to build');
 $('#timer-toggle').onclick=()=>{if(timerRunning){timerSeconds=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));timerRunning=false;}else{if(timerSeconds<=0)timerSeconds=state.minutes*60;timerEnd=Date.now()+timerSeconds*1000;timerRunning=true;}updateTimerUI();};
 $('#timer-reset').onclick=()=>{timerRunning=false;timerSeconds=state.minutes*60;updateTimerUI();};$('#timer-mission').onclick=closeModal;updateTimerUI();
}
function updateTimerUI(){const t=Math.max(0,timerSeconds),formatted=`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;if($('#timer-display'))$('#timer-display').textContent=formatted;if($('#timer-toggle'))$('#timer-toggle').innerHTML=`${icon(timerRunning?'pause':'play',14)} ${timerRunning?'Pause':'Start focus'}`;if($('#focus-label'))$('#focus-label').textContent=timerRunning?`${formatted} focusing`:`${state.minutes} min focus`;}
setInterval(()=>{if(!timerRunning)return;timerSeconds=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));if(timerSeconds===0){timerRunning=false;activity();toast('A good session. Record one observation and your next small step.');}updateTimerUI();},500);
function download(name,content,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportProgress(){download(`cartridge-academy-${today()}.json`,JSON.stringify({...state,pixelProjects:exportPixelProjects()},null,2));toast('Progress and pixel art exported. Keep this file for your next device.');}
async function copyText(text,message){try{await navigator.clipboard.writeText(text);toast(message);}catch{const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity=0;document.body.append(ta);ta.select();const ok=document.execCommand('copy');ta.remove();toast(ok?message:'Select the example and copy it with Ctrl+C.');}}
window.addEventListener('hashchange',renderRoute);
document.addEventListener('keydown',e=>{
 if(e.key==='Escape')closeModal();
 if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!$('#modal-root').children.length){e.preventDefault();openSearch();}
 if(e.key==='Tab'&&$('#modal-root').children.length){const focusable=$$('button,a[href],input:not([hidden]),textarea,select', $('.modal')).filter(el=>!el.disabled),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}
});
renderShell();renderRoute();
